#include <stdio.h>
#include <string.h>

int main(int argc, char *argv[]) {
    const char *s = "";
    if (argc >= 2) {
        s = argv[1];
    }
    int balanced = 1;               // assume balanced until proven otherwise
    char stack[1024];                // simple fixed‑size stack (enough for typical inputs)
    int sp = 0;                     // stack pointer

    for (size_t i = 0; s[i] != '\0'; ++i) {
        char c = s[i];
        if (c == '(' || c == '[' || c == '{') {
            if (sp >= (int)sizeof(stack)) { // overflow – treat as unbalanced
                balanced = 0;
                break;
            }
            stack[sp++] = c;               // push opening bracket
        } else if (c == ')' || c == ']' || c == '}') {
            if (sp == 0) {                 // nothing to match
                balanced = 0;
                break;
            }
            char open = stack[--sp];        // pop and compare
            if ((c == ')' && open != '(') ||
                (c == ']' && open != '[') ||
                (c == '}' && open != '{')) {
                balanced = 0;
                break;
            }
        }
        // all other characters are ignored
    }

    if (sp != 0) { // leftover openings
        balanced = 0;
    }

    puts(balanced ? "BALANCED" : "UNBALANCED");
    return 0;
}
}
